public static List<Fold> Folds(int size, int count) {
    List<Fold> folds = new();
    for (int k = 0; k < count; k++) {
        List<int> train = new(), test = new();
        for (int i = 0; i < size; i++)
            (i % count == k ? test : train).Add(i);
        folds.Add(new Fold(train, test));
    }
    return folds;
